if (triangulation.number_of_faces() == 0) return;

std::unordered_set<Triangulation::Face_handle> visited;
std::queue<Triangulation::Face_handle> queue;

for (auto fit = triangulation.faces_begin(); fit != triangulation.faces_end(); ++fit) {
    fit->info().is_exterior = false;
}

for (auto fit = triangulation.faces_begin(); fit != triangulation.faces_end(); ++fit) {
    if (fit->is_constrained(0) || fit->is_constrained(1) || fit->is_constrained(2)) {
        continue;
    }
    if (visited.find(fit) == visited.end()) {
        queue.push(fit);
        visited.insert(fit);
        fit->info().is_exterior = true;

        while (!queue.empty()) {
            Triangulation::Face_handle f = queue.front();
            queue.pop();

            for (int i = 0; i < 3; ++i) {
                Triangulation::Edge e(f, i);
                if (triangulation.is_constrained(e)) {
                    continue;
                }

                Triangulation::Face_handle neighbor = f->neighbor(i);
                if (neighbor == nullptr) {
                    continue;
                }

                if (visited.find(neighbor) == visited.end()) {
                    visited.insert(neighbor);
                    neighbor->info().is_exterior = true;
                    queue.push(neighbor);
                }
            }
        }
    }
}

for (auto fit = triangulation.faces_begin(); fit != triangulation.faces_end(); ++fit) {
    if (visited.find(fit) == visited.end()) {
        fit->info().is_exterior = false;
    }
}
// END_CODE

